function loadNiche(key){activeKey=key;const p=profile();$('brand').value=p.brand;$('value-prop').value=p.value;$('pain-points').value=p.pain;batch=[];batchId='';batchSaved=false;renderCards();updateMaster()}
function saveNiche(){profile().brand=$('brand').value.trim()||profile().brand;profile().value=$('value-prop').value.trim();profile().pain=$('pain-points').value.trim();try{localStorage.setItem('swarm-niches',JSON.stringify(profiles))}catch{};if(crmContext?.business){const b=crmContext.business;const patch={name:profile().brand||b.name,initial:(profile().brand||b.name||'B').charAt(0).toUpperCase(),businessProfile:{...(b.businessProfile||{}),offer:profile().value,differentiator:profile().pain}};window.parent.postMessage({type:'swarm:update-business',businessId:b.id,patch},location.origin);crmContext.business={...b,...patch}};updateMaster();invalidateBatch();notify('Niche and business context saved')}
function onCrmMessage(event){if(event.origin!==location.origin||!event.data?.type?.startsWith('swarm:'))return;const d=event.data;if(d.type==='swarm:context'){crmContext=d.context;const b=crmContext.business||{};const p=b.businessProfile||{};const savedRun=(b.swarmRuns||[]).at(-1);if(savedRun){batchId=savedRun.id;batch=savedRun.videos||[];batchSaved=true}else{batchId='';batch=[];batchSaved=false}if(b.name)$('brand').value=b.name;if(p.offer||b.description)$('value-prop').value=p.offer||b.description;if(p.differentiator||p.restrictions)$('pain-points').value=p.differentiator||p.restrictions;try{const local=JSON.parse(localStorage.getItem(`swarm-${b.id}`)||'null');const localIsNewer=local&&(!savedRun||Date.parse(local.updatedAt||0)>Date.parse(savedRun.updatedAt||savedRun.createdAt||0));if(localIsNewer&&Array.isArray(local.videos)&&local.videos.length===5){batchId=local.id;batch=local.videos;batchSaved=false}}catch{}batch=batch.map(video=>{if(video.videoPreview?.startsWith('blob:')&&!video.videoBlob?.size&&!video.videoUrl){video.videoPreview='';video.videoBlob=null;video.renderState=video.voiceUrl?'Narration saved · render again':'Narration needed · render again'}return video});if(batch[0]?.voiceId){batch=batch.map(video=>({...video,voiceId:serviceVoiceId(video.voiceId),voice:serviceVoiceId(video.voiceId)}));$('voice-id').value=batch[0].voiceId}$('crm-link-status').textContent=`Connected · ${b.name||'business'}`;$('crm-link-status').classList.add('connected');$('crm-business-summary').textContent=`${b.name||'Business'} · ${b.industry||'Niche'} · ${p.audience||b.audience||'Audience not set'} · ${b.websiteUrl||'No website added'} · ${b.logoUrl?'Logo available':'Logo not uploaded'}`;$('crm-workflow-context').textContent=workflowContext();renderAssets();updateSoundtrackOptions();renderCards();updateMaster()}else if(d.type==='swarm:save-result'){if(!d.ok)notify(d.error||'CRM save failed');else if(d.runId)notify('Prompt edits saved to CRM');else notify('Business assets saved to CRM')}else if(d.type==='swarm:run-saved'){if(d.ok){batchSaved=true;const quality=$('bot-0');quality.className='bot quality-bot done';quality.querySelector('.bot-status').textContent='COMPLETE';notify(`Saved ${d.postCount} drafts to CRM · ${d.taskQueued?'Engineer review queued':'CRM drafts saved'}`)}else{const quality=$('bot-0');quality.className='bot quality-bot error';quality.querySelector('.bot-status').textContent='NEEDS ATTENTION';$('progress-label').textContent=`Quality Bot · CRM save failed: ${d.error||'unknown error'}`;notify(d.error||'Could not save batch to CRM')}}}
function renderAssets(){const assets=crmContext?.business?.assets||[];$('asset-list').innerHTML=[...(crmContext?.business?.logoUrl?[{id:'current-logo',name:'Current logo',url:crmContext.business.logoUrl,type:'image/logo'}]:[]),...assets].map(a=>`<div class="asset-item"><a href="${escapeHTML(a.url)}" target="_blank" rel="noreferrer">${escapeHTML(a.name)}</a>${a.type?.startsWith('image/')?`<button class="text-button" data-logo="${escapeHTML(a.id)}">Set logo</button>`:''}${a.id!=='current-logo'?`<button class="text-button" data-remove="${escapeHTML(a.id)}">Remove</button>`:''}</div>`).join('')||'<div class="asset-help">No uploaded assets yet.</div>';document.querySelectorAll('[data-logo]').forEach(button=>button.addEventListener('click',()=>{const asset=assets.find(a=>a.id===button.dataset.logo);if(asset){crmContext.business.logoUrl=asset.url;window.parent.postMessage({type:'swarm:update-business',businessId:crmContext.business.id,patch:{logoUrl:asset.url}},location.origin);$('crm-business-summary').textContent=`${crmContext.business.name} · Logo selected from business assets`}}));document.querySelectorAll('[data-remove]').forEach(button=>button.addEventListener('click',()=>{const remaining=assets.filter(a=>a.id!==button.dataset.remove);crmContext.business.assets=remaining;window.parent.postMessage({type:'swarm:update-business',businessId:crmContext.business.id,patch:{assets:remaining}},location.origin);renderAssets();invalidateBatch()}))}
async function uploadBusinessAssets(event){const files=[...(event.target.files||[])];if(!files.length||!crmContext?.business){notify('Connect a CRM business before uploading assets');return}const current=[...(crmContext.business.assets||[])];for(const file of files){try{const url=await window.websim.upload(file);current.push({id:`asset-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,name:file.name,url,type:file.type||'application/octet-stream',uploadedAt:new Date().toISOString()});notify(`Uploaded ${file.name}`)}catch(error){notify(error.message||`Could not upload ${file.name}`)}}crmContext.business.assets=current;window.parent.postMessage({type:'swarm:update-business',businessId:crmContext.business.id,patch:{assets:current}},location.origin);renderAssets();updateSoundtrackOptions();invalidateBatch();event.target.value=''}
function updateSoundtrackOptions(){const select=$('soundtrack'),assets=(crmContext?.business?.assets||[]).filter(a=>String(a.type||'').startsWith('audio/'));select.querySelectorAll('option[data-upload]').forEach(option=>option.remove());assets.forEach(asset=>{const option=document.createElement('option');option.value=asset.id;option.dataset.upload='1';option.textContent=`${asset.name} · uploaded audio`;select.appendChild(option)})}
function snapshot(){if(crmContext?.business){const b=crmContext.business;const p=b.businessProfile||{};return {...profile(),label:b.industry,brand:$('brand').value.trim()||b.name,value:$('value-prop').value.trim()||p.offer||b.description||'',pain:$('pain-points').value.trim()||p.restrictions||p.differentiator||'',business:b}}return {...profile(),brand:$('brand').value.trim(),value:$('value-prop').value.trim(),pain:$('pain-points').value.trim()}}
function serviceVoiceId(id){return ['en-female','rachel','domi'].includes(id)?'en-female':'en-male'}
function workflowContext(){const w=crmContext?.workflow;if(!w)return 'No CRM workflow connected.';return (w.steps||[]).filter(s=>s.enabled).map(s=>`${s.name} (${crmContext.bots?.find(b=>b.id===s.botId)?.name||s.botId}): ${s.instructions}`).join('\n')}
function updateMaster(){const p=snapshot();$('master-prompt').textContent=`[WEBSIM VIDEO SWARM MASTER PROMPT]\nCreate exactly 5 distinct 30–60 second ${$('aspect').value} videos for every selected CRM business.\nBusiness: ${p.brand} · Industry: ${p.business?.industry||activeKey.toUpperCase()} · Niche: ${p.business?.businessProfile?.subNiche||p.label}\nValue proposition: ${p.value}\nAudience, restrictions, and claims guardrails: ${p.pain}\n\n1. SCRIPT WRITER BOT — write a complete spoken script for the target duration, a different hook angle for every video, a clear CTA, and a tone / factual-claims check. Do not invent client results, testimonials, or metrics.\n2. VOICE & AUDIO BOT — use the selected ${$('voice-id').selectedOptions[0]?.textContent} narrator, speak the complete written hook, script, and CTA verbatim, apply ${$('speech-rate').value}× playback rate, and mix the soundtrack at ${$('music-volume').value}%. Include generated narration in each final video.\n3. B-ROLL & VISUAL BOT — create a unique shot list, Flux/Midjourney image prompts, camera motion cues, and relevant stock search tags. Never reuse one generic visual plan across all five.\n4. AVATAR & TALKING HEAD BOT — specify model, framing, gesture cues, and mouth-sync parameters for avatar concepts. Human avatar mix target: ${$('avatar-ratio').value}%.\n5. REMOTION ASSEMBLY BOT — provide executable Remotion / FFmpeg JSON, captions and timing, mixed audio, and ${$('aspect').value==='9:16'?'1080×1920 vertical':$('aspect').value} output resolution.\n\nPreserve five clearly different concepts: AI Talking Head, B-Roll Showcase, Kinetic Typography, Case Study, and Myth Buster. B-roll mix target: ${$('broll-ratio').value}%. Each needs its own pacing, color/motion grammar, scenes, audio, and script angle. Do not copy public research or reuse unsupported claims.\n\nCRM context is supplemental: analyze the selected business, uploaded assets, open niche/database information, bots, and enabled workflow context. CRM workflow prompts are read-only and must not be altered. These Swarm Engine prompts and controls are editable here.`}
function makeBatch(){
  const p=snapshot(),ratio=$('aspect').value,voiceId=$('voice-id').value,voiceLabel=$('voice-id').selectedOptions[0].textContent;
  const workflow=workflowContext().slice(0,2500),facts=p.business?JSON.stringify({industry:p.business.industry,subNiche:p.business.businessProfile?.subNiche,description:p.business.description,profile:p.business.businessProfile,audience:p.business.audience,tone:p.business.tone,colors:p.business.websiteInsights?.colors}).slice(0,2500):'';
  const references=researchSources.slice(0,4).map(s=>`${s.title||s.platform}: ${s.snippet||''} ${s.url||''}`).join('\n');
  const formats=[
    {title:'AI Talking Head',style:'AI talking head',angle:'direct-to-camera founder perspective',visual:'A presenter-led opening, mid-shot with expressive hand gestures, clean studio lighting, direct eye contact; alternate close-up and medium shots.'},
    {title:'B-Roll Showcase',style:'B-roll showcase',angle:'show-don’t-tell visual demonstration',visual:'A 6-shot cinematic montage of real process, product details, hands at work, workspace and final result; slow push-ins, rack focus and purposeful match cuts.'},
    {title:'Kinetic Typography',style:'kinetic typography',angle:'bold contrarian problem / solution reveal',visual:'Oversized kinetic words, percussive text wipes, high contrast cards, quick punch-ins and animated underline callouts; no presenter.'},
    {title:'Case Study',style:'case study',angle:'transparent process breakdown without fabricated outcomes',visual:'A three-chapter timeline: starting challenge, work/process, next step; use labeled diagrams and verified facts only; never invent client names or results.'},
    {title:'Myth Buster',style:'myth buster',angle:'question, nuance, and evidence-led correction',visual:'Question-card cold open, split-screen claim vs reality, evidence/source card, then a clear practical takeaway; use measured colors and no misleading before/after.'}
  ];
  const avatarSlots=Math.round(Number($('avatar-ratio').value)/20),brollSlots=Math.round(Number($('broll-ratio').value)/20);
  const businessName=p.business?.name||p.brand,offer=p.value||'the offer described by this business',rawPain=p.business?.businessProfile?.painPoints||p.business?.businessProfile?.challenges||p.pain||'',pain=/^(avoid|do not|don't|never|must not)/i.test(rawPain.trim())?'standing out in a crowded market and earning audience trust':rawPain||'a common customer challenge';
  return formats.map((f,i)=>{
    const title=p.business?`${p.business.industry||'Business'} · ${f.title}`:`${p.label||activeKey} · ${f.title}`;
    const seconds=Math.min(Number($('duration').value),durations[i]);
    const hook=[`What if ${pain.split(/[,.]/)[0].toLowerCase()} did not have to be the norm?`,`Watch how the right details change the way ${businessName} works.`,`One clear idea can cut through a crowded feed.`,`Here is the process behind a stronger ${p.business?.industry||activeKey} campaign.`,`Let’s test a common ${p.business?.industry||activeKey} assumption.`][i];
    const cta=`Explore ${businessName} and see whether ${offer} fits your needs.`;
    const spokenScript=`${hook} ${businessName} works with people facing ${pain}. The approach starts by understanding the audience and the real problem, then choosing a focused creative direction. ${offer} is the offer; the right next step depends on your goals and context. ${i===1?'Look closely at the process, the craft, and the small choices that make the work feel specific.':i===2?'Here is the useful distinction: strong creative is not just more content; it is a clear message built for the people it needs to reach.':i===3?'First, define the challenge. Next, show the work and decisions. Finally, agree on what success should mean before results are claimed.':i===4?'The practical takeaway is to ask what evidence supports a claim, who it applies to, and what conditions could change the answer.':'A good conversation begins with the audience, the message, and a realistic plan.'} ${cta}`;
    const ssml=buildNarrationSsml(spokenScript,hook,Number($('speech-rate').value));
    const assets=(p.business?.assets||[]).slice(0,8).map(a=>`${a.name}: ${a.url}`).join('\n').slice(0,1500);
    const script=`[SCRIPT WRITER BOT · ${f.title} · ${seconds}s]\nHOOK ANGLE: ${f.angle}\nHOOK (0–3s): “${hook}”\nFULL SPOKEN SCRIPT:\n${spokenScript}\nCTA: “${cta}”\nTONE CHECK: ${p.business?.tone||voiceLabel}; confident, specific and human. Claims are limited to supplied business facts; no guaranteed results or invented testimonials.`;
    const visuals=`[B-ROLL & VISUAL BOT · UNIQUE SHOT PLAN]\nFormat: ${f.style} · B-roll mix target ${$('broll-ratio').value}% · ${i<brollSlots?'B-roll-forward treatment':'format-specific visual treatment'}\n${f.visual}\nShot list: 1) Hook frame tailored to ${businessName}. 2) Detail/process shot. 3) Audience problem in context. 4) Show this offer: ${offer}. 5) Branded takeaway and CTA.\nAI image prompts: documentary, brand-consistent ${p.business?.industry||activeKey} visuals; use uploaded business assets as reference; avoid generic stock aesthetics and copyrighted marks.\nCamera: ${i===1?'slow dolly + macro focus pulls':i===2?'snap pans + kinetic type tracking':i===3?'measured lateral moves + diagram reveals':i===4?'split-screen push + evidence-card hold':'stable eye-level framing + subtle push-in'}.\nStock tags: ${p.business?.industry||activeKey}, authentic process, professional workspace, brand details.\nCRM workflow context (read-only): ${workflow}\nBusiness facts: ${facts}\nResearch inspiration only: ${references}\nUploaded assets: ${assets}`;
    const avatarMode=i<avatarSlots;
    const avatar=`[AVATAR & TALKING HEAD BOT]\nMode: ${avatarMode?'Presenter / human avatar included':'No presenter; visual-led format'}\nNarration: ${voiceLabel}; use an authorized business avatar only.\nGesture cues: ${i===0?'open-hand hook, measured emphasis, relaxed close':i===3?'small enumerating gestures at each step':'subtle natural gestures'}\nFraming: ${ratio==='9:16'?'vertical chest-up, eyes in upper third':'medium shot'}; mouth-sync to generated voice track; preserve natural pauses.`;
    const render={batchId,videoIndex:i+1,title,format:ratio,durationSeconds:seconds,voiceId,voiceName:voiceLabel,speechRate:Number($('speech-rate').value),soundtrack:$('soundtrack').value,style:f.style,shotPlan:f.visual,voiceTrack:'',businessAssets:(p.business?.assets||[]).map(a=>a.url),timeline:{scenes:[{start:0,end:Math.round(seconds*.18),purpose:'Format-specific hook'},{start:Math.round(seconds*.18),end:Math.round(seconds*.8),purpose:f.angle},{start:Math.round(seconds*.8),end:seconds,purpose:'CTA'}],captions:{font:'Inter ExtraBold',color:'#FFFFFF',highlight:'#00E8F2',animation:['speaker-safe','cinematic-cut','word-pop','chapter-build','claim-reveal'][i]},audio:{voice:voiceLabel,voiceId,rate:Number($('speech-rate').value),ssml,pauses:[{after:'hook',ms:500},{before:'CTA',ms:350}],soundtrack:$('soundtrack').value,musicVolumePercent:Number($('music-volume').value),duckingDb:-16},output:{width:ratio==='16:9'?1920:1080,height:ratio==='16:9'?1080:ratio==='1:1'?1080:1920,fps:30,codec:'h264',container:'mp4'}}};
    return {videoNum:i+1,title,style:f.style,angle:f.angle,avatarMode,brollEmphasis:i<brollSlots,duration:`${seconds}s`,durationSeconds:seconds,aspectRatio:ratio,hook,cta,spokenScript,ssml,voiceId,voice:voiceId,voiceUrl:'',script,visuals,avatar,render,approved:false,renderState:'Concept ready'};
  });
}
function invalidateBatch(){if(batch.length){batch=[];batchId='';batchSaved=false;renderCards()}}
function renderCards(){if(!batch.length)batch=makeBatch();$('video-cards').innerHTML=batch.map((v,i)=>{const preview=v.videoPreview||v.videoUrl;return `<article class="video-card"><div class="video-info"><div class="video-index">V${i+1}</div><div><div class="video-title">${escapeHTML(v.title)}<span class="duration-tag">${v.duration}</span>${v.approved?'<span class="duration-tag">APPROVED</span>':''}</div><div class="video-style">◈ &nbsp;${escapeHTML(v.style)} · ${preview?'Final video ready':v.renderState||'Prompt package ready'}</div></div></div>${preview?`<video class="video-preview" controls playsinline preload="metadata" src="${escapeHTML(preview)}"></video>`:''}<div class="video-actions"><button class="button muted" data-video-action="${i}" data-action="inspect">⌘ &nbsp;Edit prompts</button><button class="button muted" data-video-action="${i}" data-action="render">${preview?'↻ Rebuild video':'▶ Render video'}</button>${preview?`<button class="button muted" data-video-action="${i}" data-action="approve">${v.approved?'✓ Approved · Export JSON':'Approve & Export'}</button><button class="button muted" data-video-action="${i}" data-action="download">↓ ${v.videoUrl?'Download MP4':'Create MP4'}</button>`:''}</div></article>`}).join('')}
