async function renderOne(i){if(running)return;running=true;try{setBotPhase(1,`Voice & Audio Bot · refreshing edited voice track ${i+1}/5`);await generateVoiceover(batch[i],i);setBotPhase(4,`Rebuilding edited video ${i+1}/5`);await qualityRetry(`render for video ${i+1}`,()=>renderVideo(i,p=>{$('progress-bar').style.width=`${p}%`;$('progress-value').textContent=`${p}%`;$('progress-label').textContent=`Rebuilding video ${i+1} · ${p}%`}),()=>Boolean(batch[i].videoBlob?.size>10000&&batch[i].videoPreview));saveLocalRun();if(batchSaved)pushEditedRun();notify(`Video ${i+1} rebuilt`)}catch(e){const quality=$('bot-0');quality.className='bot quality-bot error';quality.querySelector('.bot-status').textContent='NEEDS ATTENTION';$('progress-label').textContent=`Quality Bot · ${e.message}`;notify(e.message)}finally{running=false;renderCards()}}
function approveVideo(i){const v=batch[i];if(!v.videoPreview&&!v.videoUrl){notify('Render the voiced video before approving it');return}v.approved=true;v.approvedAt=new Date().toISOString();const config={project:'Swarm Engine',batchId,videoIndex:i+1,title:v.title,script:v.spokenScript,voiceover:{voiceId:v.voiceId,voiceUrl:v.voiceUrl,speechRate:Number($('speech-rate').value),ssml:v.ssml},visuals:v.visuals,avatar:v.avatar,remotionFfmpeg:v.render};downloadJson(config,`swarm-video-${i+1}-render.json`);renderCards();saveLocalRun();if(batchSaved)pushEditedRun();notify(`Video ${i+1} approved · render JSON exported`)}
function downloadJson(payload,name){const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function downloadMp4(i){const v=batch[i];if(v.videoUrl){const a=document.createElement('a');a.href=v.videoUrl;a.download=`swarm-video-${i+1}.mp4`;a.target='_blank';a.click();return}if(!v.videoBlob){notify('Render this video before creating its MP4');return}if(!window.websim?.upload){notify('MP4 transcoding is available in the signed-in CRM preview');return}try{notify(`Creating high-quality MP4 for video ${i+1}…`);const url=await window.websim.upload(v.videoBlob,{transcode:true});v.videoUrl=url;renderCards();saveLocalRun();if(batchSaved)pushEditedRun();const a=document.createElement('a');a.href=url;a.download=`swarm-video-${i+1}.mp4`;a.target='_blank';a.click();notify('High-quality MP4 is ready')}catch(error){notify(error.message||'MP4 export failed')}}
function openVideo(i){modalVideo=i;$('modal-title').textContent=`Video ${i+1} · ${batch[i].title}`;$('prompt-modal').classList.remove('hidden');showTab('script')}
function showTab(tab){modalTab=tab;document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));const v=batch[modalVideo];$('modal-output').value=tab==='render'?typeof v.render==='string'?v.render:JSON.stringify(v.render,null,2):v[tab]||''}
function savePromptEdit(){if(!batch[modalVideo])return;const value=$('modal-output').value;if(modalTab==='render'){try{batch[modalVideo].render=JSON.parse(value)}catch{batch[modalVideo].render=value}}else batch[modalVideo][modalTab]=value;if(modalTab==='script'){const match=value.match(/FULL SPOKEN SCRIPT:\s*([\s\S]*?)(?:\nCTA:|$)/);if(match)batch[modalVideo].spokenScript=match[1].trim();batch[modalVideo].ssml=buildNarrationSsml(batch[modalVideo].spokenScript,batch[modalVideo].hook,Number($('speech-rate').value));batch[modalVideo].voiceUrl=''}batch[modalVideo].approved=false;if(batch[modalVideo].videoPreview)batch[modalVideo].renderState='Prompt edited · rebuild required';saveLocalRun();if(batchSaved){clearTimeout(saveTimer);saveTimer=setTimeout(pushEditedRun,700)}}
function durableVideos(){return batch.map(({videoBlob,videoPreview,...video})=>({...video,videoPreview:video.videoUrl||''}))}
function saveLocalRun(){if(!batchId)return;const run={id:batchId,title:crmContext?.business?.name||$('brand').value,videos:durableVideos(),updatedAt:new Date().toISOString(),sources:researchSources};try{localStorage.setItem(`swarm-${crmContext?.business?.id||'local'}`,JSON.stringify(run))}catch{}}
function persistRun(){if(!crmContext?.business){saveLocalRun();return}const run={id:batchId,title:crmContext.business.name,videos:durableVideos(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),sources:researchSources,workflowName:crmContext.workflow?.name};try{localStorage.setItem(`swarm-${crmContext.business.id}`,JSON.stringify(run))}catch{}window.parent.postMessage({type:'swarm:save-run',businessId:crmContext.business.id,runId:batchId,title:run.title,run,drafts:batch.map(v=>({title:v.title,style:v.style,script:v.script,visuals:v.visuals,avatar:v.avatar,render:v.render,videoUrl:v.videoUrl,approved:v.approved})),summary:`${batch.length} rendered videos for ${crmContext.business.industry}; ${researchSources.length} public references; workflow ${run.workflowName||'default'}.`},location.origin)}
function pushEditedRun(){if(!crmContext?.business)return;const run={id:batchId,title:crmContext.business.name,videos:durableVideos(),updatedAt:new Date().toISOString(),sources:researchSources};window.parent.postMessage({type:'swarm:update-run',businessId:crmContext.business.id,runId:batchId,run},location.origin)}
function closeModal(){clearTimeout(saveTimer);if(batchSaved)pushEditedRun();$('prompt-modal').classList.add('hidden')}
async function copyText(text,message){try{await navigator.clipboard.writeText(text)}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}notify(message)}
function exportConfig(){if(!batch.length)batch=makeBatch();const payload={project:'Swarm Engine',batchId,niche:activeKey,business:crmContext?.business?.name||$('brand').value,industry:crmContext?.business?.industry||profile().label,aspectRatio:$('aspect').value,voiceId:$('voice-id').value,speechRate:Number($('speech-rate').value),soundtrack:$('soundtrack').value,soundtrackVolumePercent:Number($('music-volume').value),mix:{humanAvatarPercent:Number($('avatar-ratio').value),brollPercent:Number($('broll-ratio').value)},videos:batch.map((v,i)=>({videoIndex:i+1,title:v.title,format:v.style,durationSeconds:v.durationSeconds,script:v.spokenScript,voiceover:{voiceId:v.voiceId,voiceUrl:v.voiceUrl,ssml:v.ssml},shotList:v.visuals,avatar:v.avatar,remotionFfmpeg:v.render,approved:v.approved}))};downloadJson(payload,`swarm-batch-${activeKey}-render-code.json`);notify('Five-video Remotion / FFmpeg batch code exported')}
function notify(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
